window.NMR_EXPERIMENT = Object.freeze({"meta":{"number":"6","slug":"chapter-6","kind":"chapter","title":"Introduction to NMR of Biomolecules in H2O","titleZh":"水溶液生物分子 NMR 导论","pages":[{"id":"source-83","pdfPage":83,"bookPage":75,"en":"content/pages/source-83.en.html","zh":"content/pages/source-83.zh.html"},{"id":"source-84","pdfPage":84,"bookPage":76,"en":"content/pages/source-84.en.html","zh":"content/pages/source-84.zh.html"},{"id":"source-85","pdfPage":85,"bookPage":77,"en":"content/pages/source-85.en.html","zh":"content/pages/source-85.zh.html"},{"id":"source-86","pdfPage":86,"bookPage":78,"en":"content/pages/source-86.en.html","zh":"content/pages/source-86.zh.html"},{"id":"source-87","pdfPage":87,"bookPage":79,"en":"content/pages/source-87.en.html","zh":"content/pages/source-87.zh.html"},{"id":"source-88","pdfPage":88,"bookPage":80,"en":"content/pages/source-88.en.html","zh":"content/pages/source-88.zh.html"},{"id":"source-89","pdfPage":89,"bookPage":81,"en":"content/pages/source-89.en.html","zh":"content/pages/source-89.zh.html"},{"id":"source-90","pdfPage":90,"bookPage":82,"en":"content/pages/source-90.en.html","zh":"content/pages/source-90.zh.html"},{"id":"source-91","pdfPage":91,"bookPage":83,"en":"content/pages/source-91.en.html","zh":"content/pages/source-91.zh.html"},{"id":"source-92","pdfPage":92,"bookPage":84,"en":"content/pages/source-92.en.html","zh":"content/pages/source-92.zh.html"},{"id":"source-93","pdfPage":93,"bookPage":85,"en":"content/pages/source-93.en.html","zh":"content/pages/source-93.zh.html"},{"id":"source-94","pdfPage":94,"bookPage":86,"en":"content/pages/source-94.en.html","zh":"content/pages/source-94.zh.html"},{"id":"source-95","pdfPage":95,"bookPage":87,"en":"content/pages/source-95.en.html","zh":"content/pages/source-95.zh.html"},{"id":"source-96","pdfPage":96,"bookPage":88,"en":"content/pages/source-96.en.html","zh":"content/pages/source-96.zh.html"},{"id":"source-97","pdfPage":97,"bookPage":89,"en":"content/pages/source-97.en.html","zh":"content/pages/source-97.zh.html"},{"id":"source-98","pdfPage":98,"bookPage":90,"en":"content/pages/source-98.en.html","zh":"content/pages/source-98.zh.html"},{"id":"source-99","pdfPage":99,"bookPage":91,"en":"content/pages/source-99.en.html","zh":"content/pages/source-99.zh.html"},{"id":"source-100","pdfPage":100,"bookPage":92,"en":"content/pages/source-100.en.html","zh":"content/pages/source-100.zh.html"},{"id":"source-101","pdfPage":101,"bookPage":93,"en":"content/pages/source-101.en.html","zh":"content/pages/source-101.zh.html"},{"id":"source-102","pdfPage":102,"bookPage":94,"en":"content/pages/source-102.en.html","zh":"content/pages/source-102.zh.html"},{"id":"source-103","pdfPage":103,"bookPage":95,"en":"content/pages/source-103.en.html","zh":"content/pages/source-103.zh.html"},{"id":"source-104","pdfPage":104,"bookPage":96,"en":"content/pages/source-104.en.html","zh":"content/pages/source-104.zh.html"},{"id":"source-105","pdfPage":105,"bookPage":97,"en":"content/pages/source-105.en.html","zh":"content/pages/source-105.zh.html"}],"figurePlacements":{"source-86":[{"source":0,"before":"图 6.1 渐进闪的常规,参数输入窗口."}],"source-88":[{"source":0,"before":"图 6.2 gs-Mode 窗口显示O1选择和 (接近) 响应 FID."}],"source-90":[{"source":0,"before":"6.3 图表:使用500MHz的以过度和水压制方法获得的酶/H2O光谱的多谱显示.最高光谱是没有水压制的,剩下的光谱上到下面是文本顺序."}],"source-93":[{"source":0,"before":"6.4 图表: 酶/H2O样品的2D水源-气频谱在500 MHz."}],"source-97":[{"source":0,"before":"图6.5 2D 1H15N 500 MHz的基素/H2O样品的HSQC频谱."}],"source-99":[{"source":0,"before":"图A6.1.1 图图表前显示的 gradshim 的输入窗口. 注意,高z6 显示为 SHIMGROUP输入."}],"source-100":[{"source":0,"before":"图A6.1.2 模图为Z模图的模图,在模图绘制过程完成后显示.模图如下:Z1,红色;Z2,蓝色;Z3,绿色绿色;Z4,深绿灰色;Z5,灰色灰色."}],"source-104":[{"source":0,"before":"图 A6.4.1 显示15N HSQC实验的 edasp 显示器,代表一个两频谱仪,F1 作为1H和F2 作为15N. 这张图片来自一个四频谱仪;一个两频谱仪只"},{"source":1,"before":"图 A6.4.2 对于15N HSQC实验的四通道谱仪,F2 (15N) 频道通过FCU3向第二个X放大器进行调节.第二个X放大器将连接到反向探测器的15N端口"}]},"chapter":"Introduction to NMR of Biomolecules in H2O","navigationSections":[{"id":"section-source-83-1","pageId":"source-83","title":"Introduction to NMR of Biomolecules in H2O","titleZh":"H2O 中生物分子 NMR 导论","kind":"section"},{"id":"section-source-83-2","pageId":"source-83","title":"OVERVIEW","titleZh":"概述","kind":"section"},{"id":"section-source-83-3","pageId":"source-83","title":"SAMPLE AND SPECTROMETER REQUIREMENTS","titleZh":"样品与谱仪要求","kind":"section"},{"id":"section-source-84-4","pageId":"source-84","title":"ACTIVITIES","titleZh":"实验内容","kind":"section"},{"id":"section-source-84-5","pageId":"source-84","title":"Part 1—Lysozyme Spectra—Shimming and Pulse Calibration","titleZh":"第 1 部分——溶菌酶谱：匀场与脉冲校准","kind":"part"},{"id":"section-source-87-6","pageId":"source-87","title":"Part 2—Lysozyme Spectra—Water Suppression Using","titleZh":"第 2 部分——溶菌酶谱：水抑制","kind":"part"},{"id":"section-source-91-7","pageId":"source-91","title":"Part 3—Lysozyme Spectra—Water Suppression Using","titleZh":"第 3 部分——溶菌酶谱：水抑制","kind":"part"},{"id":"section-source-92-8","pageId":"source-92","title":"Part 4—Lysozyme Spectra—2D NOESY with WATERGATE Water","titleZh":"第 4 部分——溶菌酶谱：用 WATERGATE 抑水的二维 NOESY","kind":"part"},{"id":"section-source-94-9","pageId":"source-94","title":"Part 5—Ubiquitin Spectra—Shimming, Pulse Calibration and","titleZh":"第 5 部分——泛素谱：匀场、脉冲校准与","kind":"part"},{"id":"section-source-94-10","pageId":"source-94","title":"Part 6—Ubiquitin 2D 13C HSQC (Heteronuclear Single-","titleZh":"第 6 部分——泛素二维 13C HSQC（异核单量子）","kind":"part"},{"id":"section-source-96-11","pageId":"source-96","title":"Part 7—Ubiquitin 2D 15N HSQC Experiment Setup and","titleZh":"第 7 部分——泛素二维 15N HSQC 实验设置与","kind":"part"},{"id":"section-source-97-12","pageId":"source-97","title":"Part 8—Ubiquitin 2D HSQC Experiments Data Processing","titleZh":"第 8 部分——Ubiquitin 2D HSQC 实验的数据处理","kind":"part"},{"id":"section-source-98-13","pageId":"source-98","title":"SUMMARY","titleZh":"总结","kind":"section"},{"id":"section-source-98-14","pageId":"source-98","title":"APPENDIX 6.1 MAPPING SHIM PROFILES IN GRADSHIM","titleZh":"附录 6.1 在 gradshim 中绘制匀场剖面","kind":"section"},{"id":"section-source-101-15","pageId":"source-101","title":"APPENDIX 6.2 PRESAT180 PULSE SEQUENCE","titleZh":"附录 6.2 PRESAT180 脉冲序列","kind":"section"},{"id":"section-source-102-16","pageId":"source-102","title":"APPENDIX 6.3 X-NUCLEUS PULSE CALIBRATION","titleZh":"附录 6.3 X 核脉冲校准","kind":"section"},{"id":"section-source-103-17","pageId":"source-103","title":"APPENDIX 6.4 ROUTING FOR THE 15N RF CHANNEL IN THE","titleZh":"附录 6.4 15 N 射频通道的路由","kind":"section"}]},"english":{"source-83":"<h3>CHAPTER 6</h3>\r\n<h3>Introduction to NMR of Biomolecules in H2O</h3>\r\n<h3>OVERVIEW</h3>\r\n<p>For this chapter we will turn our attention to a special sub-field of modern NMR spectroscopy, specifically, the spectroscopy of biomolecules in water. First, we will use a standard sample of 5 mM lysozyme in 90% H2O/10% D2O to investigate a variety of water-suppression techniques, and to run the frequently-used 2D NOESY experiment. Then, we will use another standard sample, this time 1 mM 13C- and 15N-labeled ubiquitin, also in 90% H2O/10% D2O, to acquire heteronuclear correlation experiments based on the HSQC scheme. For both samples we will investigate gradient shimming and pulse calibration. The material covered in this chapter is in Chapters 6 and 10 of the Claridge book.</p>\r\n<h3>SAMPLE AND SPECTROMETER REQUIREMENTS</h3>\r\n<p>This chapter’s exercises will use samples G and H. If you do not have these two commercial samples available you may substitute your own protein or peptide samples. Keep in mind that any sample you use to replace the ubiquitin sample must be both 13C- and 15N-labeled if you want to run both of the HSQC experiments presented in this chapter. However, if you have a protein/peptide with just one label (e.g., 13C or 15N) you could run only the experiment involving that nucleus and skip the other.</p>\r\n<p>A spectrometer equipped with at least three RF channels (1H, X, and Y) and an inverse triple-resonance Z-gradient probe (typically 1H–13C–15N or 1H–13C–BB with BB tuned to 15N, usually referred to as a TXI or TBI probe) would be the ideal configuration to perform all the experiments in this chapter. If you have only a two-channel spectrometer at your disposal, however, the experiments will still work as we have presented them, since for simplicity’s sake we do not employ</p>\r\n\r\n","source-84":"<p>decoupling of the second X nucleus (Y nucleus) when acquiring the HSQC data. Since we are using pulsed field gradient experiments the spectrometer and probe must be equipped with the appropriate field gradient hardware. Also, in order for water suppression to work well while obtaining good sensitivity, the probe should be of the “inverse” type or at least be specified to perform water suppression. If this is not the case the experiments may still be carried out but the results will be sub-optimal.</p>\r\n<h3>ACTIVITIES</h3>\r\n<h3>Part 1—Lysozyme Spectra—Shimming and Pulse Calibration</h3>\r\n<p>1. Put in the lysozyme sample, lock it (use the solvent “H2O 1 D2O”), allow the sample temperature time to equilibrate (ca. 5 min) then tune the probe. Do not shim the sample. Leave sample spinning OFF. Load the 1H standard parameters and set the following in ased:</p>\r\n<h3>TD</h3>\r\n<h3>16K</h3>\r\n<h3>NS</h3>\r\n<p>1</p>\r\n<h3>DS</h3>\r\n<p>0</p>\r\n<h3>SWH</h3>\r\n<p>16 (ppm)</p>\r\n<h3>RG</h3>\r\n<p>1</p>\r\n<h3>D1</h3>\r\n<p>2</p>\r\n<h3>P1</h3>\r\n<p>1</p>\r\n<p>Then set the following processing parameters:</p>\r\n<h3>SI</h3>\r\n<h3>16K</h3>\r\n<h3>LB</h3>\r\n<p>1</p>\r\n<p>2. Obtain the 1H spectrum using the current shims. Copy this spectrum to procno 2 (wrp 2). Most likely you will only see a large peak from water in this spectrum; very high vertical expansions may reveal weak protein peaks. If the signal from the water peak is too intense (i.e., the spectrum is distorted even with RG 5 1), reduce the P1 duration until you are able to get an undistorted spectrum. 3. We will now use 1H gradient shimming to shim the sample. The type of gradient shimming procedure we will use depends upon the version of TopSpin you are using. If you are using a spectrometer with TopSpin version 1.x, please skip to step 4. If you are using a</p>\r\n","source-85":"<p>spectrometer with TopSpin version 2.x or newer, please keep reading this paragraph. Starting with TopSpin version 2 Bruker introduced a new automated shimming routine called “TopShim” which is based on gradient shimming. TopShim may be executed with no user input beyond entering the command topshim. It also may be invoked from the “Spectrometer”-“Shim control” pulldown/pullright menu; this method actually starts the command topshim gui which brings up a menu requiring some user input, although the default settings usually suffice. Therefore, use either of these methods (topshim command or menu-driven) to start TopShim, and wait for it to complete. After it has completed, skip to step 6. Note: Gradient shimming as described in step 4 is still available on spectrometers with TopSpin versions 2 or newer, if you care to use it. 4. Type gradshim to enter the gradient shimming routine. In the Gradient Shimming window that pops up check that the probe type listed under the “Current Probe” heading is correct, check with your spectrometer administrator if you are in doubt. Next, enter, check, and/or select the following (as in Figure 6.1):</p>\r\n<p>Shimming Method: 1D (1D gradient shimming using 1H observe)</p>\r\n<h3>DISK:</h3>\r\n<p>/opt/topspin (or whatever directory path is used with your spectrometer)</p>\r\n<h3>USER:</h3>\r\n<p>your user login id</p>\r\n<p>deflt1d1h (under heading “Iteration Control File”)</p>\r\n<h3>FILENAME:</h3>\r\n<p>5. Click “Start Gradient Shimming” to start the process. After the Z-axis gradient shimming completes it will display the fieldmap it obtained for the sample. Note: The gradient shimming routine requires that the shim gradient profiles have been determined correctly for your spectrometer/probe/ nucleus combination. This is referred to as “shim mapping.” If this has not been done, then gradient shimming will not work. If you want to carry out this process (with the permission of your spectrometer administrator) it is presented in Appendix 6.1. Otherwise, just click the “Exit” button in the Gradient Shimming window to terminate the routine. In this case you will need to shim the samples manually. 6. Make sure that your 1H dataset from step 2 is loaded, you may have to load it manually after gradient shimming completes. Now reacquire the 1H spectrum. Using the multiple display mode (.md), compare this spectrum with the first spectrum you obtained which was copied to procno 2; use the command rep 2 (read procno 2) in the</p>\r\n","source-86":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-086-fig-1.webp\" alt=\"Figure from source page 86.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 6.1 Gradient shimming routine, parameter input window.</p>\r\n<p>multiple display mode to do this. Print out a region of the spectrum for comparison. 7. Duplicate to a new expno. Set the chemical shift of the H2O peak to 4.7 ppm and then put the transmitter frequency (O1) directly in the center of the H2O peak. Rerun the spectrum. Make a mental note of the intensity of the water line compared to the protein signals. 8. Duplicate to a new expno. Set or confirm that PULPROG 5 zg, then find the 1H 90° pulse calibration as in Chapter 1, Part 3, step 3. Use this calibrated pulse for all the lysozyme experiments run in this laboratory. You may use the paropt au program to automate the pulse calibration process. Due to the presence of salt in the sample, the p90 (hence the p360) is expected to be longer than the default calibration value. Note that for P1 durations approaching the p90 or p270 value, you may see some distortion in the spectrum from the intense H2O signal, specifically, the H2O signal may show some dispersive components on its edges.</p>\r\n","source-87":"<h3>Part 2—Lysozyme Spectra—Water Suppression Using</h3>\r\n<h3>Presaturation-Based Methods</h3>\r\n<p>1. Copy step 8 (above) to a new expno. We will now run the first watersuppression experiment using the simplest method, presaturation. Set the following in ased:</p>\r\n<h3>PULPROG</h3>\r\n<p>zgpr</p>\r\n<h3>TD</h3>\r\n<p>8k</p>\r\n<h3>NS</h3>\r\n<p>16 (or larger multiple of 8, if needed; this applies to all experiments in this Part)</p>\r\n<h3>DS</h3>\r\n<p>8</p>\r\n<h3>P1/PL1</h3>\n<p>1H 90° pulse calibration from step 7, above</p>\n<h3>PL9</h3>\r\n<p>66 (dB) presaturation power</p>\r\n<p>2. We will need to optimize the value of O1 to ensure that the transmitter is as accurately centered on-resonance as possible. When this is the case the FID should show no or very little oscillation in its residual water signal. Variations in O1 of a few Hz or even tenths of Hz can be critical to the performance of presaturation. Type gs to enter the go-setup mode—in this mode the spectrometer acquires one scan of the pulse sequence and repeats it indefinitely, without saving any data. You will see a new FID displayed with every repetition. The gs-Mode window will show a box with various tabs to allow you to select a parameter to optimize (Figure 6.2). Click the “Offset” tab and a slider will show up to allow you to adjust the O1 parameter while you observe the FID (there is only one offset, O1, in the presaturation experiment). Change the “sensitivity” setting to 1. For this experiment we need to adjust the value of O1 to get the FID to show no oscillations, just a smooth, or nearly smooth, decay. This is easiest to see when using the FID display which shows the two channels separately (the “unshuffled” display—green box in figure). The integrated FID area is displayed in the acquisition status bar at the bottom of the window, and the value is updated with every scan. The integrated FID area will be at a minimum when the water suppression is optimized. When you have obtained the optimum O1, click “Save” and “Stop” to save the optimized O1 value and to halt the gs-operation. 3. You may also adjust the PL9 value to reduce the residual water signal (up to a minimum attenuation of 51 dB—check with your spectrometer administrator for the specific limit on the</p>\r\n","source-88":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-088-fig-1.webp\" alt=\"Figure from source page 88.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 6.2 gs-Mode window showing O1 selection and (near) on-resonance FID.</p>\r\n<p>spectrometer and probe you are using) as much as possible. This is best assessed by running the experiment and looking at the resulting spectrum, then repeating the process with a new PL9 value 3 dB lower than the previous value (e.g., 66-63-60, etc.). Reductions in the residual water signal will be apparent. Do not decrease the attenuation so much so that distortions arise in the spectrum, or that the sample temperature or the lock signal become unstable. 4. Finally, increase the value of RG as much as possible without triggering error messages from the spectrometer or causing distortions in the spectrum. Try to obtain an RG value of ca. 32 or greater. This will provide better dynamic range for the acquisition. When you are satisfied that you have obtained the best spectrum possible, obtain your final, fully optimized spectrum.</p>\r\n","source-89":"<p>5. Duplicate to a new expno. We will now use the 1D-NOESY pulse sequence to try to improve the water suppression further. Set the following:</p>\r\n<h3>PULPROG</h3>\r\n<p>noesypr1d</p>\r\n<h3>D8</h3>\r\n<p>1 ms (millisecond)</p>\r\n<h3>D11</h3>\r\n<p>30 ms</p>\r\n<p>All other parameters are the same. Run the new experiment. 6. Copy to a new expno. We will now use the presat180 scheme (reference 73 in Chapter 10 of the Claridge book) and compare the resulting spectrum quality with the previous two spectra. If your spectrometer does not have this pulse sequence installed, you will have to set it up yourself (with your spectrometer administrator’s permission). If this is the case please see Appendix 6.2 for the pulse sequence and related instructions. Then, set the following:</p>\r\n<h3>PULPROG</h3>\r\n<p>presat180</p>\r\n<h3>D16</h3>\n<p>200 µs (microseconds)</p>\n<h3>P11</h3>\n<p>500 µs (180° shaped pulse)</p>\n<h3>PL0</h3>\r\n<p>120 (dB)</p>\r\n<h3>SP1</h3>\r\n<p>PL1 + 10 dB (shaped pulse power—must be optimized manually)</p>\n<h3>SPNAM1</h3>\r\n<p>Crp60,0.5,20.1 (shapefile for pulse)</p>\r\n<h3>GPNAM1</h3>\r\n<p>SINE.50 (gradient shaped pulse file)</p>\r\n<h3>GPZ1</h3>\r\n<p>5 (%)</p>\r\n<h3>P16</h3>\r\n<p>500 µs (gradient pulse time)</p>\r\n<p>7. The value of PL1 + 10 dB given above for SP1 is just a starting point; for example, if your default PL1 is 0 dB, start with +10 dB for SP1. Now we will optimize the value of SP1, but this time we have to actually run the experiment with at least 4 scans (or a multiple thereof) to assess the correct value for SP1. To carry out the optimization, set a starting value of SP1 (e.g., PL1 + 10 dB) and acquire and process the data. Then, change the SP1 value by 1 dB and repeat the process. Compare the results to the prior results. You are aiming to improve the water-peak suppression while</p>\n","source-90":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-090-fig-1.webp\" alt=\"Figure from source page 90.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 6.3 Multiple-spectra display of lysozyme / H2O spectra obtained using presaturation-based watersuppression methods at 500 MHz. Uppermost spectrum is with no water suppression, remaining spectra upper to lower are in the order of the text.</p>\r\n<p>maintaining the intensities of the non-H2O peaks in the spectrum. It will take some experimentation to find the optimum SP1 value; it may be larger or smaller (in the absolute sense, i.e., 1 or 2 ) than the PL1 1 10 dB starting point we suggest. In the authors’ experience, an SP1 value corresponding to a p90 of about 36 µs (approximately equal to the TOCSY 90° spinlock pulse power (PL10) value used in Chapter 4, Part 3, step 2, see also Note 2 for that step) will give acceptable results. 8. After optimizing SP1, run the optimized experiment. 9. After obtaining all the data, use the multiple display mode (.md) to compare the three presaturation experiments (steps 2, 3 and 5). Note any differences in the residual water signal intensity and width (Figure 6.3).</p>\r\n","source-91":"<h3>Part 3—Lysozyme Spectra—Water Suppression Using</h3>\r\n<h3>“WATERGATE”-Based Methods</h3>\r\n<p>1. Copy the last experiment to a new expno. We will now run the first experiment using the simplest WATERGATE method. Set the following:</p>\r\n<h3>PULPROG</h3>\r\n<p>zggpwg</p>\r\n<h3>P11</h3>\r\n<p>1200 µs (90° selective pulse)</p>\r\n<h3>SP1</h3>\r\n<p>power level for P11, ca. 40 (dB, check using edprosol)</p>\r\n<h3>SPNAM1</h3>\r\n<p>sinc1.1000</p>\r\n<h3>GPNAM1</h3>\r\n<p>SINE.100</p>\r\n<h3>GPZ1</h3>\r\n<p>20</p>\r\n<h3>P16</h3>\r\n<p>1 ms</p>\r\n<p>2. Now optimize the value of SP1, using gs as before, looking for the value which gives the minimum FID intensity. RG may need to be reduced if the estimate for SP1 was off. 3. After optimizing SP1, run the experiment. 4. Copy to a new expno. We will now use another variant of WATERGATE which uses the 3-9-19 sequence. Set the following:</p>\r\n<h3>PULPROG</h3>\r\n<p>p3919gp</p>\r\n<h3>D19</h3>\r\n<p>62, 80, or 100 µs (delay for binomial excitation, these values for 800, 600 or 500 MHz spectrometers, respectively)</p>\r\n<h3>P0</h3>\r\n<p>Same as P1</p>\r\n<h3>P27/PL18</h3>\r\n<p>Use same values as for P1/PL1</p>\r\n<p>All other parameters are the same. Rerun. 5. Copy to a new expno. We will now use a variant of the WATERGATE sequence which uses the w5 excitation/suppression sequence. Set the following:</p>\r\n<h3>PULPROG</h3>\r\n<p>zggpw5</p>\r\n<h3>GPZ1</h3>\r\n<p>34</p>\r\n<h3>GPZ2</h3>\r\n<p>22</p>\r\n<p>All other parameters are the same. Rerun. 6. After obtaining the data, enter the multiple display mode (.md) to compare the three WATERGATE experiments (steps 3, 4, and 5). Note any differences in the residual water signal intensity and width.</p>\r\n","source-92":"<h3>Part 4—Lysozyme Spectra—2D NOESY with WATERGATE Water</h3>\r\n<h3>Suppression</h3>\r\n<p>1. Copy the 1H WATERGATE w5 spectrum (Part 3, step 5) to a new expno. Set the following in eda:</p>\r\n<h3>PULPROG</h3>\r\n<p>noesygpphw5</p>\r\n<p>1-2-3 1-2 (change 1D–2D)</p>\r\n<h3>FnMODE</h3>\n<p>States-TPPI</p>\n<h3>TD</h3>\r\n<h3>2K (F2), 256 (F1)</h3>\r\n<h3>ND_010</h3>\r\n<p>1</p>\r\n<h3>SW (Hz)</h3>\n<p>F2 and F1 both the same as the 1H presaturation spectrum</p>\n<p>Note: ND_010 must be set before the SW values are entered! 2. Now use ased and enter the following:</p>\r\n<h3>NS</h3>\n<p>8 (depending on your spectrometer’s 1H sensitivity, multiples of 8 may be needed)</p>\n<h3>RG</h3>\r\n<p>2 times current value</p>\r\n<h3>D8</h3>\r\n<p>70 ms (mixing time)</p>\r\n<h3>D16</h3>\n<p>200 µs</p>\n<h3>D19</h3>\n<p>62, 80, or 100 µs (see Part 3, step 4)</p>\n<h3>P27/PL18</h3>\r\n<p>Use same values as for P1/PL1</p>\r\n<h3>PL9</h3>\r\n<p>78 (dB, only a low power level is needed for presaturation with WATERGATE in use)</p>\r\n<h3>GPNAM1,2</h3>\r\n<p>SINE.100</p>\r\n<h3>GPZ1</h3>\r\n<p>34</p>\r\n<h3>GPZ2</h3>\r\n<p>22</p>\r\n<h3>P16</h3>\r\n<p>500 µs (gradient pulse)</p>\r\n<p>3. Now go into edp or the ProcPars tab and set the following processing parameters:</p>\r\n<h3>SI</h3>\r\n<h3>2K (F2), 1K (F1)</h3>\r\n<h3>SR</h3>\r\n<p>F1 value same as F2</p>\r\n<h3>WDW</h3>\r\n<p>QSINE (both dimensions)</p>\r\n<h3>SSB</h3>\r\n<p>2 (both dimensions)</p>\r\n<h3>PHCO (F1)</h3>\r\n<p>90 (phase corrections in F1)</p>\r\n<h3>PHC1 (F1)</h3>\r\n<p>2180</p>\r\n<h3>PH_mod</h3>\n<p>pk (both dimensions)</p>\n<h3>BC_mod</h3>\n<p>qpol (F2)</p>\n<h3>FCOR</h3>\n<p>1 (both dimensions—weighting factor for first data points)</p>\r\n<h3>MC2</h3>\r\n<p>States-TPPI</p>\r\n","source-93":"<p>4. Run this experiment with zg. This will take about 1.25 h with 8 scans per increment. 5. To set the phase corrections in F2, do rser 1, process and phase the 1D spectrum as was done in Chapter 4, Part 9, step 2, except here we will phase the spectrum to show positive peaks (in Chapter 4 we phased it to be inverted—strictly speaking the NOESY here should be inverted as well but it is conventional in protein NMR to phase the NOESY positive). Save the phase corrections to the 2D dataset. 6. Process with xfb. The spectrum should appear to be phased nearly correctly with all peaks positive. This large protein molecule will have nOe peaks with the same phase as the diagonal. Use the 2D phasing routine to touch up the phasing if necessary. 7. The bas command may be used to flatten the 2D baseplane, if needed (Figure 6.4).</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-093-fig-1.webp\" alt=\"Figure from source page 93.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 6.4 2D WATERGATE-NOESY spectrum of the lysozyme/H2O sample at 500 MHz.</p>\r\n","source-94":"<h3>Part 5—Ubiquitin Spectra—Shimming, Pulse Calibration and</h3>\r\n<h3>1D 1H Spectrum</h3>\r\n<p>1. Put in the ubiquitin sample, lock it (use the solvent “H2O 1 D2O”), and tune the probe for 1H. Follow the steps from Part 1 of this laboratory to get the initial spectrum (including gradient or manual shimming) and do the 1H pulse calibration. Then use the noesypr1d or the zgpww5 (your choice, make sure to set up everything correctly) pulse sequence to obtain the 1D 1H spectrum with water suppression. The easiest way to do this is to duplicate the experiment run earlier in this Chapter to a new experiment, and update the 1H p90 pulse calibrations before running it on the ubiquitin sample. This serves as a quick evaluation of the sample quality.</p>\r\n<h3>Part 6—Ubiquitin 2D 13C HSQC (Heteronuclear Single-</h3>\r\n<h3>Quantum) Experiment Setup and Acquisition</h3>\r\n<p>1. We will first set up the 1H–13C HSQC experiment. Copy the 1D spectrum you obtained in Part 5 to a new experiment. In the new experiment set the following in eda:</p>\r\n<h3>PULPROG</h3>\r\n<p>hsqcetgpsi</p>\r\n<p>1-2-3 1-2</p>\r\n<p>FnMODE Echo-Antiecho</p>\r\n<h3>TD</h3>\r\n<h3>2K (F2), 256 (F1)</h3>\r\n<h3>NUC2</h3>\r\n<p>13C, then “save,” cf. Chapter 2, Part 2, step 3 for the specific steps for your software version; this step sets up the decoupling (F2) channel properly</p>\r\n<h3>NUC1 (F1)</h3>\r\n<p>13C—this step is important!—sets up the frequency reference in F1</p>\r\n<h3>O2P</h3>\r\n<p>70 (standard value for the center of the 13C spectrum window)</p>\r\n<h3>ND_010</h3>\r\n<p>2</p>\r\n<h3>SW (F1)</h3>\r\n<p>ca. 150 ppm (standard value for the 13C spectrum window)</p>\r\n<p>Note: ND_010 and NUC1 (F1) must be set before the SW (F1) value is entered! The NUC2 entry sets up the decoupling (i.e., the second RF) channel for the correct nucleus (in this case 13C). The NUC1 (F1) entry ensures that the software knows that the nucleus/frequency to be used for referencing the frequency calculations in F1 is 13C. If this is not correct, the sweep width calculations will be wrong. Be aware, however, that these two parameters (NUC2 and NUC1 (F1)) are not always the same.</p>\r\n","source-95":"<p>2. In ased set the following:</p>\r\n<h3>NS</h3>\n<p>2 or 4 (depending on your instrument’s 1H sensitivity)</p>\n<h3>DS</h3>\r\n<p>16</p>\r\n<h3>RG</h3>\r\n<p>64–1k, depending on the spectrometer, or set using rga</p>\r\n<h3>CNST2</h3>\r\n<p>135 (Hz, the one-bond JC–H—optimized for aliphatic CH)</p>\r\n<h3>D1</h3>\r\n<p>2</p>\r\n<h3>D16</h3>\r\n<p>200 u</p>\r\n<h3>D24</h3>\r\n<p>926 u (1/8 J)</p>\r\n<h3>ZGOPTNS</h3>\r\n<p>Leave this field blank (flag for enabling 15N decoupling which we will not use)</p>\r\n<h3>P1/PL1</h3>\r\n<p>1H p90 calibration done in Part 5, above</p>\r\n<h3>P28</h3>\r\n<p>1 m</p>\r\n<h3>P3/PL2</h3>\r\n<p>13C p90 calibration (from Chapter 1 or from edprosol)</p>\r\n<h3>CPDPRG2</h3>\r\n<p>garp (CPD sequence for broadband decoupling of 13C)</p>\r\n<h3>PCPD2</h3>\r\n<p>50–70 (microseconds) (for 800–500 MHz spectrometers)</p>\r\n<h3>PL12</h3>\r\n<p>ca. 12 dB (power level for 50–70 µs 13C p90—check using edprosol)</p>\r\n<h3>GPNAM1,2</h3>\r\n<p>SINE.100</p>\r\n<h3>GPZ1</h3>\r\n<p>80 (%)</p>\r\n<h3>GPZ2</h3>\r\n<p>20.1</p>\r\n<h3>P16</h3>\r\n<p>1 m</p>\r\n<p>3. In edp set the following:</p>\r\n<h3>SI</h3>\r\n<p>2K in both dimensions</p>\r\n<h3>SF (F1)</h3>\r\n<p>Set to the BF2 for 13C</p>\r\n<h3>WDW</h3>\r\n<p>QSINE (both dimensions)</p>\r\n<h3>SSB</h3>\r\n<h3>2 (F2), 3 (F1)</h3>\r\n<h3>PHCO</h3>\r\n<p>0 (both)</p>\r\n<h3>PHC1</h3>\r\n<p>0 (both)</p>\r\n<h3>PH_mod</h3>\n<p>pk (both)</p>\n<h3>BC_mod</h3>\n<p>qpol (F2), no (F1)</p>\n<h3>FCOR</h3>\r\n<p>0.5 (both)</p>\r\n<h3>MC2</h3>\r\n<p>echo-antiecho</p>\r\n<p>4. Check the probe tuning on 13C.</p>\r\n<p>5. Optional: For completeness, the 13C p90 calibration should be checked using this sample prior to acquiring the HSQC spectrum. However, even though the sample is 13C-labeled the low concentration usually precludes direct observation of the 13C signal on most spectrometers. Appendix 6.3 gives the procedure for carrying out this operation.</p>\r\n","source-96":"<p>However, if your spectrometer can directly observe the 13C spectrum of this sample, you may use the direct-observe method to check this calibration (cf. Chapter 1, Part 4). 6. Run this experiment with zg. This will take about 20 min with 2 scans per increment.</p>\r\n<h3>Part 7—Ubiquitin 2D 15N HSQC Experiment Setup and</h3>\r\n<h3>Acquisition</h3>\r\n<p>1. Copy the 1H–13C HSQC dataset to the next expno. We will now set up the 15N HSQC using the 13C HSQC as a template. In the new experiment set the following in eda:</p>\r\n<h3>TD</h3>\r\n<h3>64 (F1)</h3>\r\n<h3>NUC2</h3>\r\n<p>15N, then “save,” see notes in Part 6, above</p>\r\n<h3>NUC1 (F1)</h3>\r\n<p>15N (see notes in Part 6)</p>\r\n<h3>O2P</h3>\r\n<p>117 (typical value for the center of the 15N spectrum window)</p>\r\n<h3>ND_010</h3>\r\n<p>2</p>\r\n<h3>SW (F1)</h3>\n<p>ca. 40 ppm (normal value for the 15N spectrum window)</p>\n<p>Note: ND_010 and NUC1 (F1) must be set before the SW (F1) value is entered! 2. In ased set the following:</p>\n<h3>NS</h3>\n<p>4 (or a multiple of 4, depending on your spectrometer’s 1H sensitivity)</p>\n<h3>DS</h3>\r\n<p>16</p>\r\n<h3>RG</h3>\r\n<p>64–1k, depending on the spectrometer, or set using rga</p>\r\n<h3>CNST2</h3>\r\n<p>92 (Hz, the one-bond J(NH))</p>\r\n<h3>D24</h3>\n<p>2.7 ms (1/4J—optimized for NH)</p>\n<h3>ZGOPTNS</h3>\n<p>Leave this field blank (flag for enabling 13C decoupling)</p>\n<h3>P3/PL2</h3>\n<p>15N p90 calibration (from your spectrometer administrator or edprosol)</p>\n<h3>PCPD2</h3>\n<p>180–220 µs (for 800–500 MHz spectrometers)</p>\n<h3>PL12</h3>\n<p>ca. 10 dB (power level for 180–220 µs 15N p90—check as for P3/PL2 above)</p>\n<h3>GPZ2</h3>\r\n<p>8.1</p>\r\n<p>3. Type edasp and check the routing of the 15N FCU to its amplifier. This will need to be checked with your spectrometer administrator, since this can be different for different hardware configurations. We show examples of two different common routing possibilities in Appendix 6.4.</p>\r\n","source-97":"<p>4. In edp set the following:</p>\r\n<h3>SI</h3>\r\n<h3>512 (F1)</h3>\r\n<p>Set to the BF1 for 15N</p>\r\n<h3>SF (F1)</h3>\r\n<p>5. Check or carry out the probe tuning for 15N. 6. Optional: For completeness, the 15N p90 calibration should be checked prior to acquiring the HSQC spectrum. The procedure in Appendix 6.3 can also be used for this operation. 7. Run this experiment with zg. This will take about 20 min with 2 scans per increment.</p>\r\n<h3>Part 8—Ubiquitin 2D HSQC Experiments Data Processing</h3>\r\n<p>1. Go to the first ubiquitin HSQC dataset. 2. Use xfb to process the HSQC datasets in turn. 3. After transformation, all experiments may need to be phased manually in both dimensions. When carrying out the 2D phasing, phase</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-097-fig-1.webp\" alt=\"Figure from source page 97.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 6.5 2D 1H–15N HSQC spectrum of the ubiquitin/H2O sample at 500 MHz.</p>\r\n","source-98":"<p>the F2 dimension (rows, R) first, before attempting the F1 (columns, C) dimension. Iterate through the F2, F1 phasing sequence if necessary. 4. Set the contour levels in each experiment. Normally these spectra are not displayed or plotted with projections, but you may include an F2 (1H) projection if you wish. Note that since the 2D spectra are not decoupled the cross-peaks may not align with those of the 1D 1H spectrum precisely (Figure 6.5).</p>\r\n<h3>SUMMARY</h3>\r\n<p>Your lab report should include the following:</p>\r\n<p>1. Printout of the lysozyme sample spectrum with the H2O line at full intensity (Part 1, step 2). 2. Lysozyme water-suppression spectra from Parts 2 and 3, six spectra in all. Plot each with the same region and vertical scaling to try to compare the signal intensities to residual H2O. 3. Printout of the lysozyme NOESY spectrum with correct projections. 4. Ubiquitin noesypr1d or zgpww5 spectrum from Part 5. 5. Ubiquitin HSQC spectra from Parts 6 and 7. Ensure that the F2 projection is correct on each plot. 6. Suggested questions for consideration: a. What did you get for the 1H p90 calibration for the lysozyme</p>\r\n<p>sample? Is this different from the calibration you obtained for the quinine sample? If so, why? b. Which of the water-suppression techniques gave the best result</p>\r\n<p>in your experience? c. For the HSQC experiments, can you suggest anything that could</p>\r\n<p>be done to improve the sensitivity?</p>\r\n<h3>APPENDIX 6.1 MAPPING SHIM PROFILES IN GRADSHIM</h3>\r\n<p>If the shim gradient profiles have not been set up for the current probe, you will receive a message “No 1D shim map exists for the current probe: probe type” when starting gradshim. If this occurs you will need to create the shim maps. Do so using the following procedure, after obtaining permission from your spectrometer administrator.</p>\r\n<p>1. Exit the gradient shimming routine by clicking the “Exit” button in the Gradient Shimming window.</p>\r\n","source-99":"<p>2. Save the current shims (for later access if needed) by typing wsh</p>\r\n<h3>GSHIM.</h3>\r\n<p>3. Reenter the gradient shimming routine by typing gradshim. Check that the probe type listed under the “Current Probe” heading is correct, check with your spectrometer administrator if you are in doubt. Check that “1D” is selected for the “Shimming Method.” Note: This assumes you are using an H2O-containing sample for this procedure. Click on the “Setup” button followed by the “Shim Mapping” selection in the pop-down menu which appears. This will open a new window titled “Shim Mapping.” 4. In the Shim Mapping window enter, check, and/or select the following (as in Figure A6.1.1):</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-099-fig-1.webp\" alt=\"Figure from source page 99.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A6.1.1 Input windows of gradshim displayed prior to start of the shim mapping procedure. Note that “highz6” is shown for the SHIMGROUP input.</p>\r\n","source-100":"<p>Shim Mapping Method: 1D (1D gradient shimming using 1H observe)</p>\r\n<p>gradshim1d1h (under heading “Parameter Set”)</p>\r\n<h3>FILENAME:</h3>\r\n<h3>DISK:</h3>\r\n<p>/opt/topspin (or whatever data directory path is used with your spectrometer)</p>\r\n<h3>USER:</h3>\r\n<p>Your user login id</p>\r\n<p>5, 25 (under heading “Echo Times”)</p>\r\n<h3>TE1, TE2</h3>\r\n<h3>SHIMGROUP</h3>\r\n<p>highz (or highz6, check with your administrator)</p>\r\n<p>5. Click “Start Shim Mapping” to start the process. At this point a small window will pop up telling you that the reference shims should be stored as “GSHIM.” Since we already did this in step 2, simply click the “OK” button and the mapping process will start. After the mapping completes it will display the shim profiles it obtains, as shown in Figure A6.1.2.</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-100-fig-1.webp\" alt=\"Figure from source page 100.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A6.1.2 Shim profiles for Z-shims displayed after completion of shim mapping procedure. Shims are as follows: Z1, red; Z2, blue; Z3, light green; Z4, dark green-gray; Z5, light gray.</p>\r\n","source-101":"<h3>APPENDIX 6.2 PRESAT180 PULSE SEQUENCE</h3>\r\n<p>If your spectrometer does not have this pulse sequence installed you will need to add it using the edpul command as follows.</p>\r\n<p>1. Type edpul new to open a new editor window. 2. In the edpul window either paste in (Ctrl-V) or type in the text below starting with the “presat180” line:</p>\r\n<p>;presat180 ;1D sequence with f1 presaturation ;and adiabatic pulse inversion ;Mo and Raftery JMR (2008) 190:1–6 #include ,Avance.incl . “d12 5 10 u” “d30 5 0.5” 1 ze 2 30 m d12 pl9:f1 d1 cw:f1 ph9 4 u do:f1 p16:gp1 d16 pl0:f1 if “d30 , 1” goto 3 if “d30 . 1” goto 4 3 p11:sp1 ph29 ; d12</p>\r\n<p>“d30 5 1.5” goto 5 4 ;p11:sp2 ph29 ;d12 “d30 5 0.5” 5 p16:gp1×-1 d16 pl1:f1 p1 ph1 go 5 2 ph31 30 m mc #0 to 2 F0(zd) exit ph1 5 0 0 1 1 2 2 3 3 ph9 5 0 ph29 5 {0}×8 {1}×8 ph31 5 0 2 1 3 2 0 3 1</p>\r\n","source-102":"<p>;pl1: f1 channel - power level for pulse (default) ;pl9: f1 channel - power level for presaturation ;sp1: adiabatic inversion pulse peak power (B8 kHz) ;spnam1: Crp60,0.5,20.1 ;p1: f1 channel - 90 degree high power pulse ;p11: adiabatic inversion pulse length [500 us] ;p16: gradient pulse length [250 us to 500 us] ;d1: relaxation delay . 2 × T1 ;d12: delay for power switching [10 usec] ;d16: gradient recovery delay [50 us] ;d30: on/off switch for adiabatic pulse ;NS: 8 × n, total number of scans: NS × TD0 ;DS: 4 × n ;for z-only gradients: ;gpz1: 5% ;use gradient files: ;gpnam1: SINE.50 Make sure that if you type this in that you do not make any mistakes. You can save your input at any time (you will have to use “Save as” as described below the first time and “Save” any subsequent times). 3. Click the “Save as” button and enter presat180.hm in the “New name” text box. 4. Go to the “File” pulldown and select “Exit” to close the editor.</p>\r\n<h3>APPENDIX 6.3 X-NUCLEUS PULSE CALIBRATION</h3>\r\n<h3>USING THE gs-Mode</h3>\r\n<p>1. Go to the ubiquitin HSQC dataset (Part 6). 2. Start the 2D acquisition. As soon as the first fid is saved, read it using rser 1. Carry out the following:</p>\r\n<p>a. Type lb and enter 10, do ef, then phase the resulting spectrum</p>\r\n<p>with all peaks (excepting the residual H2O) positive. b. When finished phasing, use .s2d or click the save-2D icon</p>\r\n<p>to save the phase corrections to the HSQC dataset, followed by .ret or clicking the return icon. c. Type to2d to return to the 2D dataset. 3. Stop the current acquisition using the halt command. 4. We will now optimize the pulse calibration for the 13C (or 15N) p90 using the gs-Mode. Type gs to start, and in the gs-Mode window</p>\r\n","source-103":"<p>select “SquarePower” followed by PL2. Select the spectrum display mode using the “Execute realtime ft and show spectrum” icon (icon with an FID over a spectrum) above the FID display. Then click the “Realtime ft settings” icon (next to the previous icon) and in the popup window select “PK” for the “Phase correction mode:” option. If necessary for the spectrum quality you may also select an appropriate “Window function:” from the same menu. Click “OK” when finished. You should now be seeing a correctly-phased spectrum updated with each scan. 5. Adjust the variable parameter sensitivity down by a factor of 10. As the gs-Mode is running, adjust the PL2 value in steps of 0.5 dB to obtain a maximal signal (on average) for the protein (i.e., non-H2O) peaks of interest in your spectrum when compared with the H2O peak. Keep in mind that for the 13C HSQC this refers (generally) to the (upfield) aliphatic 1H peaks, and for the 15N HSQC this refers to the HN (downfield) 1H peaks. After the optimal value is obtained, stop the gs-operation (cf., Part 2, step 2) and save the new PL2 value using the popup window which appears upon stopping. 6. If the PL2 value changes significantly, use edprosol to recalculate the PL12 value for 13C or 15N garp decoupling. 7. The same procedure with gs can be used to check the 15N p90 prior to running the 15N HSQC experiment.</p>\r\n<h3>APPENDIX 6.4 ROUTING FOR THE 15N RF CHANNEL IN THE</h3>\r\n<h3>15N HSQC EXPERIMENT</h3>\r\n<p>The default routing of the 15N channel will depend upon the configuration of your spectrometer.</p>\r\n<p>If your spectrometer has two RF channels, then 15N by default will be on F2. In this case there is no choice to be made for the routing, you will simply have to tune the appropriate coil of the probe to 15N before you proceed with the experiment. This routing arrangement is shown in Figure A6.4.1.</p>\r\n<p>If your spectrometer has three or more RF channels, the experiment can be performed with 15N set up on F2 or F3. The more common default situation for a three- or four-channel spectrometer equipped with a triple- or quadruple-resonance inverse probe (TXI, TBI, or QXI) would be that F2 would be 13C and would be routed to the 13C</p>\r\n","source-104":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-104-fig-1.webp\" alt=\"Figure from source page 104.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A6.4.1 edasp display for 15N HSQC experiment representing a two-channel spectrometer with F1 as 1H and F2 as 15N. This picture is from a four-channel spectrometer; a two-channel spectrometer would show only the upper half of the display encompassing F1 and F2.</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-104-fig-2.webp\" alt=\"Figure from source page 104.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A6.4.2 edasp display for 15N HSQC experiment for a four-channel spectrometer with the F2 (15N) channel routed via FCU3 to the second X amplifier. The second X amplifier would be connected to the 15N port of an inverse probe.</p>\r\n<p>port on the probe, and 15N would be F3 and would be routed to the 15N port on the probe. To perform a 15N HSQC experiment with this configuration would require the use of a pulse program which employs F3 for the 15N pulses. The F3-using pulse program analogous to hsqcetgpsi we used in Part 4, above, would be hsqcetf3gpsi.</p>\r\n","source-105":"<p>However, we are using the F2-based pulse program in order to allow the same write-up to be used with (almost) any spectrometer configuration. In this case we will need to route the 15N channel in an appropriate fashion to allow the F2-based pulse program to work with a three- or more channel spectrometer. One way to do this is shown in Figure A6.4.2. Route the output from the “F2” box to the input side of the “FCU3” box, and connect the output of the “FCU3” box to the second X amplifier (by this we mean the second in the listing from the top of the display). This amplifier will typically be routed to the 15N port on an inverse probe.</p>\r\n"},"chinese":{"source-83":"<h3>第 6 章</h3>\n<h3>H2O 中生物分子 NMR 导论</h3>\n<h3>概述</h3>\n<p>本章关注现代 NMR 波谱学的一个特殊分支，即水中生物分子的波谱。首先使用 90% H2O/10% D2O 中 5 mM 溶菌酶标准样品，考察多种水抑制技术并进行常用的二维 NOESY 实验。随后使用另一种标准样品：同样溶于 90% H2O/10% D2O 的 1 mM 13C、15N 双标记泛素，采集基于 HSQC 的异核相关实验。对两种样品都将考察梯度匀场和脉冲校准。本章内容对应 Claridge 书的第 6 章和第 10 章。</p>\n<h3>样品与谱仪要求</h3>\n<p>本章练习使用样品 G 和 H。若没有这两种商业样品，可用自己的蛋白质或肽样品替代。注意：若要完成本章介绍的两项 HSQC 实验，替代泛素样品必须同时进行 13C 和 15N 标记；若蛋白质/肽只有一种标记（如 13C 或 15N），则只能进行涉及该核的实验，跳过另一项。</p>\n<p>要完成本章全部实验，理想配置是至少具有三个 RF 通道（1H、X 和 Y）以及反向三共振 Z 梯度探头的谱仪（通常为 1H–13C–15N，或 BB 调谐至 15N 的 1H–13C–BB，分别称为 TXI 或 TBI 探头）。即使只有双通道谱仪，实验仍可按本书所述进行，因为为简化操作，采集 HSQC 数据时不使用第二个 X 核（Y 核）的去耦。</p>\n","source-84":"<p>采集 HSQC 数据时不对第二个 X 核（Y 核）进行去耦。由于使用脉冲场梯度实验，谱仪和探头必须配备相应的场梯度硬件。为获得良好水抑制和灵敏度，探头应为“反向”型，或至少明确支持水抑制；否则仍可进行实验，但结果可能不理想。</p>\n<h3>实验内容</h3><h3>第 1 部分——溶菌酶谱：匀场与脉冲校准</h3>\n<p>1. 放入溶菌酶样品并锁场（溶剂用“H2O 1 D2O”），等待温度平衡约 5 min 后调谐探头。不要对样品匀场，关闭样品旋转。载入 1H 标准参数，在 <code>ased</code> 中设置：</p>\n<h3>TD</h3><h3>16K</h3><h3>NS</h3><p>1</p><h3>DS</h3><p>0</p><h3>SWH</h3><p>16 (ppm)</p><h3>RG</h3><p>1</p><h3>D1</h3><p>2</p><h3>P1</h3><p>1</p>\n<p>再设置处理参数：</p><h3>SI</h3><h3>16K</h3><h3>LB</h3><p>1</p>\n<p>2. 用当前匀场采集 1H 谱，将谱复制到 <code>procno 2</code>（<code>wrp 2</code>）。通常只能看到很大的水峰；大幅垂直放大后可能看到弱蛋白峰。若水峰信号过强（RG = 1 时谱仍失真），缩短 P1，直到获得无畸变谱。3. 现在用 1H 梯度匀场。程序取决于 TopSpin 版本；若为 TopSpin 1.x，跳到步骤 4；若为</p>\n","source-85":"<p>TopSpin 2.x 或更新版本，请继续。TopSpin 2 引入了基于梯度匀场的自动程序 TopShim。输入 <code>topshim</code> 即可运行，也可从 “Spectrometer”–“Shim control” 菜单调用 <code>topshim gui</code>。任选一种方式启动并等待完成，然后跳到步骤 6。注：TopSpin 2 及更新版本仍可使用步骤 4 的梯度匀场。4. 输入 <code>gradshim</code>。在 Gradient Shimming 窗口确认 “Current Probe” 下的探头类型正确；不确定时咨询谱仪管理员。按图 6.1 输入、检查或选择：</p>\n<p>匀场方法：1D（使用 1H 观测的一维梯度匀场）</p><h3>DISK:</h3><p>/opt/topspin（或谱仪使用的目录路径）</p><h3>USER:</h3><p>你的用户登录 ID</p><p><code>deflt1d1h</code>（“Iteration Control File”项）</p><h3>FILENAME:</h3>\n<p>5. 点击 “Start Gradient Shimming”。Z 轴梯度匀场完成后会显示样品场图。注意：程序要求已正确确定谱仪/探头/核组合的梯度匀场曲线，即完成 shim mapping；否则无法工作。若经管理员许可，可按附录 6.1 执行映射；否则点击 “Exit” 退出并手动匀场。6. 确认已载入步骤 2 的 1H 数据集（匀场完成后可能需手动载入），重新采集 1H 谱。用多谱显示模式（<code>.md</code>）与复制到 <code>procno 2</code> 的第一张谱比较；使用命令 <code>rep 2</code>（读取 procno 2）在</p>\n","source-86":"<p class=\"figure-caption\">图 6.1　梯度匀场程序的参数输入窗口。</p>\n<p>多谱显示模式中完成比较，并打印一段谱区。7. 复制到新的 <code>expno</code>。将 H2O 峰化学位移设为 4.7 ppm，把发射频率 O1 置于水峰中心，重新采集。记下水峰相对于蛋白信号的强度。8. 再复制到新的 <code>expno</code>。确认 <code>PULPROG = zg</code>，按第 1 章第 3 部分步骤 3 校准 1H 90° 脉冲。该校准值用于本实验室的所有溶菌酶实验。可用 <code>paropt au</code> 自动校准。由于样品含盐，p90（以及 p360）预计比默认值更长。P1 接近 p90 或 p270 时，强 H2O 信号边缘可能出现色散分量。</p>\n","source-87":"<h3>第 2 部分——溶菌酶谱：水抑制</h3>\r\n<h3>基于预饱和的方法</h3>\r\n<p>1. 将上面的步骤 8 复制到新的 <code>expno</code>。用最简单的预饱和法进行第一次水抑制实验，在 <code>ased</code> 中设置：</p>\r\n<h3>PULPROG</h3>\r\n<p>zgpr</p>\r\n<h3>TD</h3>\r\n<p>8k</p>\r\n<h3>NS</h3>\r\n<p>16（必要时为 8 的更大倍数；本部分所有实验均如此）</p>\r\n<h3>DS</h3>\r\n<p>8</p>\r\n<h3>P1/PL1</h3>\n<p>使用上面步骤 7 校准的 1H 90° 脉冲</p>\n<h3>PL9</h3>\r\n<p>66（dB，预饱和功率）</p>\r\n<p>2. 优化 O1，使发射频率尽可能准确地位于共振中心；此时残余水信号的 FID 应不振荡或几乎不振荡。O1 偏差数 Hz 甚至零点几 Hz 都可能影响预饱和。输入 <code>gs</code> 进入 go-setup 模式：谱仪会不断重复单次扫描，但不保存数据，每次重复都会显示新的 FID。在 gs-Mode 窗口中可以选择待优化参数（图 6.2）；单击“Offset”选项卡，利用滑块边观察 FID 边调整 O1（预饱和实验中只有 O1 一个偏置）。将“sensitivity”设为 1。目标是让 FID 平滑或近似平滑地衰减；使用分别显示两个通道的“unshuffled”FID 视图（图中绿色框）最容易观察。窗口底部采集状态栏会显示积分 FID 面积，并在每次扫描后更新；水抑制最佳时该面积达到最小。得到最佳 O1 后，单击“Save”和“Stop”保存数值并停止 gs。3. 也可调整 PL9 以进一步减小残余水信号（最低衰减可至 51 dB；具体限值须向谱仪管理员确认），</p>\n","source-88":"<p class=\"figure-caption\">图 6.2　gs-Mode 窗口，显示 O1 选择和（近似）共振状态的 FID。</p>\n<p>尽量降低残余水信号。可运行实验查看谱，再将 PL9 比前值降低 3 dB 重复（如 66、63、60）。不要降低过度而产生失真，或使样品温度、锁场信号不稳定。4. 尽可能增大 RG，避免谱仪报错或谱失真；目标约为 32 或更高，以获得更大动态范围。满意后采集最终优化谱。</p>\n","source-89":"<p>5. 复制到新的 <code>expno</code>。使用 1D-NOESY 序列进一步改善水抑制，设置：</p>\r\n<h3>PULPROG</h3>\r\n<p>noesypr1d</p>\r\n<h3>D8</h3>\r\n<p>1 ms</p>\r\n<h3>D11</h3>\r\n<p>30 ms</p>\r\n<p>其他参数不变，运行实验。6. 复制到新的 <code>expno</code>。使用 presat180 方案（Claridge 书第 10 章参考文献 73）并与前两张谱比较。若谱仪没有该序列，经管理员许可按附录 6.2 设置。然后设置：</p>\r\n<h3>PULPROG</h3>\r\n<p>presat180</p>\r\n<h3>D16</h3>\n<p>200 μs</p>\n<h3>P11</h3>\n<p>500 μs（180° 形状脉冲）</p>\n<h3>PL0</h3>\r\n<p>120（dB）</p>\r\n<h3>SP1</h3>\r\n<p>PL1 + 10 dB（成形脉冲功率，需手动优化）</p>\n<h3>SPNAM1</h3>\r\n<p>Crp60,0.5,20.1（脉冲形状文件）</p>\r\n<h3>GPNAM1</h3>\r\n<p>SINE.50（梯度形状脉冲文件）</p>\r\n<h3>GPZ1</h3>\r\n<p>5（%）</p>\r\n<h3>P16</h3>\r\n<p>500 μs（梯度脉冲时间）</p>\r\n<p>7. 上述 SP1 的 PL1 1 10 dB 仅为起始值；现在以至少 4 次扫描（或其倍数）实际运行实验，逐次将 SP1 改变 1 dB 并比较结果，以改善水峰抑制同时保持非水峰强度。</p>\r\n","source-90":"<p class=\"figure-caption\">图 6.3　500 MHz 下采用预饱和水抑制的溶菌酶/H2O 多谱显示。最上方为未抑制水的谱，其余谱自上而下按正文实验顺序排列。</p>\n<p>寻找最佳 SP1 需要试验；其绝对值可能比建议起始值 PL1 1 10 dB 大或小 1–2 dB。作者经验表明，使 p90 约为 36 μs 的 SP1（约等于第 4 章第 3 部分步骤 2 使用的 TOCSY 90° 自旋锁功率 PL10）通常可获得可接受结果。8. 优化 SP1 后运行优化实验。9. 获得全部数据后，用多谱显示（<code>.md</code>）比较三次预饱和实验（步骤 2、3、5），注意残余水信号的强度和宽度差异（图 6.3）。</p>\n","source-91":"<h3>第 3 部分——溶菌酶谱：水抑制</h3>\r\n<h3>基于 WATERGATE 的方法</h3>\r\n<p>1. 将最后一个实验复制到新的 <code>expno</code>，使用最简单的 WATERGATE 方法：</p>\r\n<h3>PULPROG</h3>\r\n<p>zggpwg</p>\r\n<h3>P11</h3>\r\n<p>1200 μs（90° 选择性脉冲）</p>\r\n<h3>SP1</h3>\r\n<p>P11 的功率，约 40（dB，用 edprosol 检查）</p>\r\n<h3>SPNAM1</h3>\r\n<p>sinc1.1000</p>\r\n<h3>GPNAM1</h3>\r\n<p>SINE.100</p>\r\n<h3>GPZ1</h3>\r\n<p>20</p>\r\n<h3>P16</h3>\r\n<p>1 ms</p>\r\n<p>2. 像之前一样用 <code>gs</code> 优化 SP1，使 FID 强度最小；若 SP1 估计不准，可能需要降低 RG。3. 优化后运行实验。4. 复制到新的 <code>expno</code>，使用 3-9-19 序列的 WATERGATE 变体：</p>\r\n<h3>PULPROG</h3>\r\n<p>p3919gp</p>\r\n<h3>D19</h3>\r\n<p>62、80 或 100 μs（双项激发延迟，分别适用于 800、600、500 MHz 谱仪）</p>\r\n<h3>P0</h3>\r\n<p>与 P1 相同</p>\r\n<h3>P27/PL18</h3>\r\n<p>与 P1/PL1 相同</p>\r\n<p>其他参数不变，重新运行。5. 复制到新的 <code>expno</code>，使用 w5 激发/抑制序列的 WATERGATE 变体：</p>\r\n<h3>PULPROG</h3>\r\n<p>zggpw5</p>\r\n<h3>GPZ1</h3>\r\n<p>34</p>\r\n<h3>GPZ2</h3>\r\n<p>22</p>\r\n<p>其他参数不变，重新运行。6. 获取数据后进入多谱显示（<code>.md</code>），比较三次 WATERGATE 实验（步骤 3、4、5），注意残余水信号的强度和宽度差异。</p>\r\n","source-92":"<h3>第 4 部分——溶菌酶谱：用 WATERGATE 抑水的二维 NOESY</h3>\r\n<h3>水抑制</h3>\r\n<p>1. 将 1H WATERGATE w5 谱（第 3 部分步骤 5）复制到新的 <code>expno</code>，在 <code>eda</code> 中设置：</p>\r\n<h3>PULPROG</h3>\r\n<p>noesygpphw5</p>\r\n<p>1-2-3 1-2（从 1D 改为 2D）</p>\r\n<h3>FnMODE</h3>\n<p>States-TPPI</p>\n<h3>TD</h3>\r\n<h3>2K (F2), 256 (F1)</h3>\r\n<h3>ND_010</h3>\r\n<p>1</p>\r\n<h3>SW (Hz)</h3>\n<p>F2 和 F1 均与 1H 预饱和谱相同</p>\n<p>注意：必须先设置 ND_010，再输入 SW。2. 进入 <code>ased</code> 并设置：</p>\r\n<h3>NS</h3>\n<p>8（取决于谱仪的 1H 灵敏度，可能需要使用 8 的倍数）</p>\n<h3>RG</h3>\r\n<p>当前值的 2 倍</p>\r\n<h3>D8</h3>\r\n<p>70 ms（混合时间）</p>\r\n<h3>D16</h3>\n<p>200 μs</p>\n<h3>D19</h3>\n<p>62、80 或 100 μs（见第 3 部分步骤 4）</p>\n<h3>P27/PL18</h3>\r\n<p>与 P1/PL1 相同</p>\r\n<h3>PL9</h3>\r\n<p>78（dB；使用 WATERGATE 时预饱和只需低功率）</p>\r\n<h3>GPNAM1,2</h3>\r\n<p>SINE.100</p>\r\n<h3>GPZ1</h3>\r\n<p>34</p>\r\n<h3>GPZ2</h3>\r\n<p>22</p>\r\n<h3>P16</h3>\r\n<p>500 μs（梯度脉冲）</p>\r\n<p>3. 进入 <code>edp</code> 或 ProcPars 选项卡，设置处理参数：</p>\r\n<h3>SI</h3>\r\n<h3>2K (F2), 1K (F1)</h3>\r\n<h3>SR</h3>\r\n<p>F1 值与 F2 相同</p>\r\n<h3>WDW</h3>\r\n<p>QSINE（两个维度）</p>\r\n<h3>SSB</h3>\r\n<p>2（两个维度）</p>\r\n<h3>PHCO (F1)</h3>\r\n<p>90（F1 相位校正）</p>\r\n<h3>PHC1 (F1)</h3>\r\n<p>2180</p>\r\n<h3>PH_mod</h3>\n<p>pk（两个维度）</p>\n<h3>BC_mod</h3>\n<p>qpol（F2）</p>\n<h3>FCOR</h3>\n<p>1（两个维度——首个数据点的加权因子）</p>\n<h3>MC2</h3>\r\n<p>States-TPPI</p>\r\n","source-93":"<p>4. 输入 <code>zg</code> 运行实验。每个增量扫描 8 次时约需 1.25 h。5. 设置 F2 相位校正：执行 <code>rser 1</code>，按第 4 章第 9 部分步骤 2 处理并调整 1D 谱；这里要将谱调成正峰（第 4 章调成倒置；严格说 NOESY 也应倒置，但蛋白质 NMR 通常将 NOESY 调为正峰）。将相位校正保存到二维数据集。6. 用 <code>xfb</code> 处理，谱图应几乎正确，所有峰为正。该大分子蛋白的 NOE 峰应与对角峰同相；必要时用二维相位程序微调。7. 如有需要，可用 <code>bas</code> 命令展平二维基线（图 6.4）。</p><p class=\"figure-caption\">图 6.4　500 MHz 下溶菌酶/H2O 样品的二维 WATERGATE-NOESY 谱。</p>\n","source-94":"<h3>第 5 部分——泛素谱：匀场、脉冲校准与</h3>\r\n<h3>1D 1H 谱</h3>\r\n<p>1. 放入泛素样品并锁场（溶剂“H2O 1 D2O”），调谐探头至 1H。按本实验第 1 部分步骤获取初始谱（包括梯度或手动匀场）并进行 1H 脉冲校准。随后选择 noesypr1d 或 zgpww5 序列获得抑水的 1D 1H 谱。最简单的方法是将本章前面运行的实验复制到新实验，并在泛素样品上运行前更新 1H p90 校准；这可快速评估样品质量。</p>\r\n<h3>第 6 部分——泛素二维 13C HSQC（异核单量子）</h3>\r\n<h3>实验设置与采集</h3>\r\n<p>1. 首先设置 1H–13C HSQC。将第 5 部分所得 1D 谱复制到新实验，在 <code>eda</code> 中设置：</p>\r\n<h3>PULPROG</h3>\r\n<p>hsqcetgpsi</p>\r\n<p>1-2-3 1-2</p>\r\n<p>FnMODE Echo-Antiecho</p>\r\n<h3>TD</h3>\r\n<h3>2K (F2), 256 (F1)</h3>\r\n<h3>NUC2</h3>\r\n<p>13C，然后保存；具体步骤参见第 2 章第 2 部分步骤 3。该项设置 F2 去耦通道。</p>\r\n<h3>NUC1 (F1)</h3>\r\n<p>13C——此步骤很重要，用于设置 F1 的频率参考。</p>\r\n<h3>O2P</h3>\r\n<p>70（13C 谱窗中心的标准值）</p>\r\n<h3>ND_010</h3>\r\n<p>2</p>\r\n<h3>SW (F1)</h3>\r\n<p>约 150 ppm（13C 谱窗的标准值）。</p>\r\n<p>注意：输入 SW (F1) 前必须先设置 ND_010 和 NUC1 (F1)。NUC2 设置正确核的去耦（第二 RF）通道，本例为 13C；NUC1 (F1) 确保软件知道 F1 频率计算所用的参考核为 13C，否则扫描宽度计算会错误。二者不一定总是相同。</p>\r\n","source-95":"<p>2. 在 <code>ased</code> 中设置：</p>\r\n<h3>NS</h3>\n<p>2 或 4（取决于仪器的 1H 灵敏度）</p>\n<h3>DS</h3>\r\n<p>16</p>\r\n<h3>RG</h3>\r\n<p>64–1k，取决于谱仪，或用 <code>rga</code> 设置</p>\n<h3>CNST2</h3>\r\n<p>135 Hz（脂肪族 CH 的一键 1J(C–H) 优化值）</p>\r\n<h3>D1</h3>\r\n<p>2</p>\r\n<h3>D16</h3>\r\n<p>200 μs</p>\r\n<h3>D24</h3>\r\n<p>926 μs（1/8J）</p>\r\n<h3>ZGOPTNS</h3>\r\n<p>留空（启用 15N 去耦的标志；本实验不使用）</p>\r\n<h3>P1/PL1</h3>\r\n<p>第 5 部分完成的 1H p90 校准</p>\r\n<h3>P28</h3>\r\n<p>1 ms</p>\r\n<h3>P3/PL2</h3>\r\n<p>13C p90 校准（来自第 1 章或 <code>edprosol</code>）</p>\r\n<h3>CPDPRG2</h3>\r\n<p>garp（用于 13C 宽带去耦的 CPD 序列）</p>\r\n<h3>PCPD2</h3>\r\n<p>50–70 μs（适用于 800–500 MHz 谱仪）</p>\r\n<h3>PL12</h3>\r\n<p>约 12 dB（50–70 μs 13C p90 的功率；用 <code>edprosol</code> 检查）</p>\r\n<h3>GPNAM1,2</h3>\r\n<p>SINE.100</p>\r\n<h3>GPZ1</h3>\r\n<p>80 (%)</p>\r\n<h3>GPZ2</h3>\r\n<p>20.1</p>\r\n<h3>P16</h3>\r\n<p>1 ms</p>\r\n<p>3. 在 <code>edp</code> 中设置：</p>\r\n<h3>SI</h3>\r\n<p>两个维度均为 2K</p>\r\n<h3>SF (F1)</h3>\r\n<p>设为 13C 的 BF2</p>\r\n<h3>WDW</h3>\r\n<p>QSINE（两个维度）</p>\r\n<h3>SSB</h3>\r\n<h3>2 (F2), 3 (F1)</h3>\r\n<h3>PHCO</h3>\r\n<p>0（两者）</p>\r\n<h3>PHC1</h3>\r\n<p>0（两者）</p>\r\n<h3>PH_mod</h3>\n<p>pk（两者）</p>\n<h3>BC_mod</h3>\n<p>qpol（F2），no（F1）</p>\n<h3>FCOR</h3>\r\n<p>0.5（两者）</p>\r\n<h3>MC2</h3>\r\n<p>echo-antiecho</p>\r\n<p>4. 检查探头在 13C 上的调谐。</p>\r\n<p>5.可选：采集 HSQC 前应使用该样品检查 13C p90 校准；但即使样品已标记 13C，低浓度通常也使大多数谱仪无法直接观察 13C 信号。附录 6.3 给出了操作步骤。</p>\r\n","source-96":"<p>若谱仪能直接观察该样品的 13C 谱，可用直接观测法检查校准（见第 1 章第 4 部分）。6. 用 <code>zg</code> 运行实验；每个增量扫描 2 次时约需 20 min。</p>\r\n<h3>第 7 部分——泛素二维 15N HSQC 实验设置与</h3>\r\n<h3>采集</h3>\r\n<p>1. 将 1H–13C HSQC 数据集复制到下一个 <code>expno</code>，以 13C HSQC 为模板设置 15N HSQC。在新实验的 <code>eda</code> 中设置：</p>\r\n<h3>TD</h3>\r\n<h3>64 (F1)</h3>\r\n<h3>NUC2</h3>\r\n<p>15N，然后保存（见上面第 6 部分说明）</p>\r\n<h3>NUC1 (F1)</h3>\r\n<p>15N（见第 6 部分说明）</p>\r\n<h3>O2P</h3>\r\n<p>117（15N 谱窗中心的典型值）</p>\r\n<h3>ND_010</h3>\r\n<p>2</p>\r\n<h3>SW (F1)</h3>\n<p>约 40 ppm（15N 谱窗的常用值）。</p>\n<p>注意：输入 SW (F1) 前必须先设置 ND_010 和 NUC1 (F1)。2. 在 <code>ased</code> 中设置：</p>\n<h3>NS</h3>\n<p>4（或 4 的倍数，取决于谱仪 1H 灵敏度）</p>\n<h3>DS</h3>\r\n<p>16</p>\r\n<h3>RG</h3>\r\n<p>64–1k，取决于谱仪，或用 <code>rga</code> 设置</p>\n<h3>CNST2</h3>\r\n<p>92 Hz（一键 J(NH)）</p>\r\n<h3>D24</h3>\n<p>2.7 ms（1/4J，针对 NH 优化）</p>\n<h3>ZGOPTNS</h3>\n<p>留空（启用 13C 去耦的标志）</p>\n<h3>P3/PL2</h3>\n<p>15N p90 校准（来自谱仪管理员或 <code>edprosol</code>）</p>\n<h3>PCPD2</h3>\n<p>180–220 μs（适用于 800–500 MHz 谱仪）</p>\n<h3>PL12</h3>\n<p>约 10 dB（180–220 μs 15N p90 的功率；按 P3/PL2 检查）</p>\n<h3>GPZ2</h3>\r\n<p>8.1</p>\r\n<p>3. 输入 <code>edasp</code>，检查 15N FCU 到其放大器的路由。由于硬件配置不同，需与谱仪管理员确认；附录 6.4 展示两种常见路由示例。</p>\r\n","source-97":"<p>4. 在 edp 中设置以下参数：</p>\n<h3>SI</h3>\n<h3>512 (F1)</h3>\n<p>将其设置为 15N 的 BF1。</p>\n<h3>SF (F1)</h3>\n<p>5. 检查或执行 15N 探头调谐。6. 可选：为完整起见，在采集 HSQC 谱前应检查 15N p90 校准；附录 6.3 的步骤也可用于此操作。7. 用 zg 运行该实验。每个增量采集 2 次扫描时，约需 20 分钟。</p>\n<h3>第 8 部分——Ubiquitin 2D HSQC 实验的数据处理</h3>\n<p>1. 进入第一个 ubiquitin HSQC 数据集。2. 依次使用 xfb 处理 HSQC 数据集。3. 变换后，可能需要在两个维度中分别手动调相。</p>\n<p class=\"figure-caption\">图 6.5 500 MHz 下 ubiquitin/H<sub>2</sub>O 样品的 2D <sup>1</sup>H–<sup>15</sup>N HSQC 谱。</p>\n","source-98":"<p>先处理 F2 维（行，R），再处理 F1 维（列，C）；必要时重复 F2、F1 调相顺序。4. 在每个实验中设置等高线级别。通常不显示或绘制投影，但如果需要，可以加入 F2（<sup>1</sup>H）投影。注意：由于 2D 谱未进行去耦合，交叉峰与 1D <sup>1</sup>H 谱中的峰可能不会完全对齐（图 6.5）。</p>\n<h3>总结</h3>\n<p>实验报告应包括以下内容：</p>\n<p>1. 溶菌酶样品谱的打印图，其中 H<sub>2</sub>O 峰保持全强度（第 1 部分，步骤 2）。2. 第 2、3 部分得到的溶菌酶抑水谱，共 6 张；使用相同的区域和纵向缩放绘制，以比较信号强度与残余 H<sub>2</sub>O。3. 带有正确投影的溶菌酶 NOESY 谱打印图。4. 第 5 部分的 ubiquitin noesypr1d 或 zgpww5 谱。5. 第 6、7 部分的 ubiquitin HSQC 谱；确保每张图的 F2 投影正确。</p>\n<p>6a. 溶菌酶样品的 <sup>1</sup>H p90 校准值是多少？与 quinine 样品所得校准值不同吗？如果不同，为什么？</p>\n<p>6b. 依你的经验，哪种抑水技术效果最好？</p>\n<p>6c. 对 HSQC 实验，有什么办法可以提高灵敏度？</p>\n<h3>附录 6.1 在 gradshim 中绘制匀场剖面</h3>\n<p>如果当前探头尚未设置梯度匀场剖面，启动 gradshim 时会收到“当前探头不存在 1D shim map：探头类型”的消息。此时需要在获得谱仪管理员许可后，按以下步骤创建匀场图。</p>\n<p>1. 在 Gradient Shimming 窗口中单击“Exit”，退出梯度匀场程序。</p>\n","source-99":"<p>2. 输入 wsh 保存当前匀场值（以后需要时可调用）。</p>\n<h3>GSHIM</h3>\n<p>3. 输入 gradshim 重新进入梯度匀场程序。检查“Current Probe”下列出的探头类型是否正确；如有疑问，请咨询谱仪管理员。确认“Shimming Method”选择为“1D”。注意：以下步骤假定使用含 H<sub>2</sub>O 的样品。单击“Setup”，再从弹出菜单中选择“Shim Mapping”，打开名为“Shim Mapping”的窗口。4. 在 Shim Mapping 窗口中按图 A6.1.1 输入、检查或选择以下项目：</p>\n<p class=\"figure-caption\">图 A6.1.1 gradshim 在开始匀场映射前显示的输入窗口。注意，SHIMGROUP 输入中显示的是“highz6”。</p>\n","source-100":"<p>匀场映射方法：1D（使用 <sup>1</sup>H 观测的 1D 梯度匀场）。</p>\n<p>gradshim1d1h（“Parameter Set”标题下的选项）。</p>\n<h3>FILENAME：</h3>\n<h3>DISK：</h3>\n<p>/opt/topspin（或谱仪所使用的数据目录路径）。</p>\n<h3>USER：</h3>\n<p>你的用户登录 ID。</p>\n<p>5、25（“Echo Times”标题下）。</p>\n<h3>TE1, TE2</h3>\n<h3>SHIMGROUP</h3>\n<p>highz（或 highz6，请与管理员确认）。</p>\n<p>5. 单击“Start Shim Mapping”开始处理。此时会弹出小窗口，提示应将参考匀场保存为“GSHIM”。由于步骤 2 已完成保存，只需单击“OK”，映射即会开始。映射完成后，将显示获得的匀场剖面，如图 A6.1.2 所示。</p>\n<p class=\"figure-caption\">图 A6.1.2 匀场映射完成后显示的 Z 匀场剖面。各匀场为：Z1 红色；Z2 蓝色；Z3 浅绿色；Z4 深绿灰色；Z5 浅灰色。</p>\n","source-101":"<h3>附录 6.2 PRESAT180 脉冲序列</h3>\n<p>如果谱仪未安装该脉冲序列，需要使用 edpul 命令按以下步骤添加。</p>\n<p>1. 输入 edpul new 打开新的编辑器窗口。2. 在 edpul 窗口中粘贴（Ctrl-V）或输入下面的文本，起始行为“presat180”： </p>\n<p>;presat180 ;1D sequence with f1 presaturation ;and adiabatic pulse inversion ;Mo and Raftery JMR (2008) 190:1–6 #include ,Avance.incl . “d12 = 10 u” “d30 = 0.5” 1 ze 2 30 m d12 pl9:f1 d1 cw:f1 ph9 4 u do:f1 p16:gp1 d16 pl0:f1 if “d30 , 1” goto 3 if “d30 . 1” goto 4 3 p11:sp1 ph29 ; d12</p>\n<p>“d30 = 1.5” goto 5 4 ;p11:sp2 ph29 ;d12 “d30 = 0.5” 5 p16:gp1×-1 d16 pl1:f1 p1 ph1 go 5 2 ph31 30 m mc #0 to 2 F0(zd) exit ph1 5 0 0 1 1 2 2 3 3 ph9 5 0 ph29 5 {0}×8 {1}×8 ph31 5 0 2 1 3 2 0 3 1</p>\n","source-102":"<p>;pl1：f1 通道脉冲功率电平（默认）；pl9：f1 通道预饱和功率电平；sp1：绝热反转脉冲峰值功率（B<sub>1</sub> 约 8 kHz）；spnam1：Crp60,0.5,20.1；p1：f1 通道高功率 90° 脉冲；p11：绝热反转脉冲长度 [500 μs]；p16：梯度脉冲长度 [250–500 μs]；d1：弛豫延迟 = 2 × T<sub>1</sub>；d12：功率切换延迟 [10 μs]；d16：梯度恢复延迟 [50 μs]；d30：绝热脉冲开关；NS：8 × n，扫描总数为 NS × TD0；DS：4 × n；仅用于 z 梯度：gpz1：5%；使用梯度文件：gpnam1：SINE.50。输入时务必不要出错。任何时候都可以保存输入（第一次用“Save as”，之后用“Save”）。3. 单击“Save as”，在“New name”文本框中输入 presat180.hm。4. 打开“File”下拉菜单并选择“Exit”关闭编辑器。</p>\n<h3>附录 6.3 X 核脉冲校准</h3>\n<h3>使用 gs 模式</h3>\n<p>1. 进入 ubiquitin HSQC 数据集（第 6 部分）。2. 启动 2D 采集。第一个 FID 保存后，使用 rser 1 读取它，并执行以下操作：</p>\n<p>a. 输入 lb 并输入 10，执行 ef，然后调相所得谱图</p>\n<p>使所有峰（残余 H<sub>2</sub>O 除外）为正。b. 调相完成后，使用 .s2d 或单击 save-2D 图标</p>\n<p>将相位校正保存到 HSQC 数据集，然后使用 .ret 或单击 return 图标返回。c. 输入 to2d 返回 2D 数据集。3. 使用 halt 命令停止当前采集。4. 现在用 gs 模式优化 <sup>13</sup>C（或 <sup>15</sup>N）p90 脉冲校准。输入 gs 启动，并在 gs 模式窗口中继续操作。</p>\n","source-103":"<p>选择“SquarePower”，再选择 PL2。使用 FID 显示器上方的“Execute realtime ft and show spectrum”图标（FID 位于谱图上方的图标）选择谱图显示模式。然后单击旁边的“Realtime ft settings”图标，在弹出窗口中将“Phase correction mode”设为“PK”。如有需要，也可在同一菜单中选择合适的“Window function”。完成后单击“OK”。此时每次扫描后都应更新并显示正确调相的谱图。5. 将变量参数的灵敏度降低 10 倍。gs 模式运行时，以 0.5 dB 为步长调节 PL2，使蛋白质（即非 H<sub>2</sub>O）目标峰相对于 H<sub>2</sub>O 峰获得最大的平均信号。对 <sup>13</sup>C HSQC，这通常指上场的脂肪族 <sup>1</sup>H 峰；对 <sup>15</sup>N HSQC，则指下场的 HN <sup>1</sup>H 峰。得到最佳值后停止 gs 操作（参见第 2 部分步骤 2），并在停止时出现的弹窗中保存新的 PL2 值。6. 如果 PL2 变化显著，使用 edprosol 重新计算 <sup>13</sup>C 或 <sup>15</sup>N garp 去耦的 PL12 值。7. 在运行 <sup>15</sup>N HSQC 前，也可用同样的 gs 程序检查 <sup>15</sup>N p90。</p>\n<h3>附录 6.4 <sup>15</sup>N 射频通道的路由</h3>\n<h3><sup>15</sup>N HSQC 实验</h3>\n<p><sup>15</sup>N 通道的默认路由取决于谱仪配置。</p>\n<p>如果谱仪有两个射频通道，则 <sup>15</sup>N 默认位于 F2。此时无需选择路由；继续实验前，只需将探头相应的线圈调谐到 <sup>15</sup>N。该路由如图 A6.4.1 所示。</p>\n<p>如果谱仪有三个或更多射频通道，则可将 <sup>15</sup>N 设置在 F2 或 F3 上进行实验。对于配备三重或四重共振逆探头（TXI、TBI 或 QXI）的三通道或四通道谱仪，更常见的默认情况是 F2 为 <sup>13</sup>C，并路由到探头的 <sup>13</sup>C</p>\n","source-104":"<p class=\"figure-caption\">图 A6.4.1 edasp 中的 <sup>15</sup>N HSQC 实验显示：双通道谱仪将 F1 设为 <sup>1</sup>H、F2 设为 <sup>15</sup>N。该图来自四通道谱仪；双通道谱仪只会显示包含 F1 和 F2 的上半部分。</p>\n<p class=\"figure-caption\">图 A6.4.2 四通道谱仪中 <sup>15</sup>N HSQC 实验的 edasp 显示：F2（<sup>15</sup>N）通道经 FCU3 路由到第二个 X 放大器；该放大器连接到逆探头的 <sup>15</sup>N 端口。</p>\n<p>要执行 <sup>15</sup>N HSQC 实验，需要使用为 <sup>15</sup>N 脉冲采用 F3 的脉冲程序。与上文第 4 部分使用的 hsqcetgpsi 对应、使用 F3 的脉冲程序是 hsqcetf3gpsi。</p>\n","source-105":"<p>不过，为了让几乎所有谱仪配置都能使用同一份说明，我们采用基于 F2 的脉冲程序。在这种情况下，需要以适当方式路由 <sup>15</sup>N 通道，使基于 F2 的脉冲程序能够在三通道或更多通道的谱仪上工作。图 A6.4.2 给出了一种连接方式：将“F2”盒的输出接到“FCU3”盒的输入端，再将 FCU3 的输出接到第二个 X 放大器（即显示列表中从上往下数的第二个）。该放大器通常会连接到逆探头的 <sup>15</sup>N 端口。</p>\n"},"figurePlacements":{"source-86":[{"source":0,"before":"图 6.1 渐进闪的常规,参数输入窗口."}],"source-88":[{"source":0,"before":"图 6.2 gs-Mode 窗口显示O1选择和 (接近) 响应 FID."}],"source-90":[{"source":0,"before":"6.3 图表:使用500MHz的以过度和水压制方法获得的酶/H2O光谱的多谱显示.最高光谱是没有水压制的,剩下的光谱上到下面是文本顺序."}],"source-93":[{"source":0,"before":"6.4 图表: 酶/H2O样品的2D水源-气频谱在500 MHz."}],"source-97":[{"source":0,"before":"图6.5 2D 1H15N 500 MHz的基素/H2O样品的HSQC频谱."}],"source-99":[{"source":0,"before":"图A6.1.1 图图表前显示的 gradshim 的输入窗口. 注意,高z6 显示为 SHIMGROUP输入."}],"source-100":[{"source":0,"before":"图A6.1.2 模图为Z模图的模图,在模图绘制过程完成后显示.模图如下:Z1,红色;Z2,蓝色;Z3,绿色绿色;Z4,深绿灰色;Z5,灰色灰色."}],"source-104":[{"source":0,"before":"图 A6.4.1 显示15N HSQC实验的 edasp 显示器,代表一个两频谱仪,F1 作为1H和F2 作为15N. 这张图片来自一个四频谱仪;一个两频谱仪只"},{"source":1,"before":"图 A6.4.2 对于15N HSQC实验的四通道谱仪,F2 (15N) 频道通过FCU3向第二个X放大器进行调节.第二个X放大器将连接到反向探测器的15N端口"}]},"navigationSections":[{"id":"section-source-83-1","pageId":"source-83","title":"Introduction to NMR of Biomolecules in H2O","titleZh":"H2O 中生物分子 NMR 导论","kind":"section"},{"id":"section-source-83-2","pageId":"source-83","title":"OVERVIEW","titleZh":"概述","kind":"section"},{"id":"section-source-83-3","pageId":"source-83","title":"SAMPLE AND SPECTROMETER REQUIREMENTS","titleZh":"样品与谱仪要求","kind":"section"},{"id":"section-source-84-4","pageId":"source-84","title":"ACTIVITIES","titleZh":"实验内容","kind":"section"},{"id":"section-source-84-5","pageId":"source-84","title":"Part 1—Lysozyme Spectra—Shimming and Pulse Calibration","titleZh":"第 1 部分——溶菌酶谱：匀场与脉冲校准","kind":"part"},{"id":"section-source-87-6","pageId":"source-87","title":"Part 2—Lysozyme Spectra—Water Suppression Using","titleZh":"第 2 部分——溶菌酶谱：水抑制","kind":"part"},{"id":"section-source-91-7","pageId":"source-91","title":"Part 3—Lysozyme Spectra—Water Suppression Using","titleZh":"第 3 部分——溶菌酶谱：水抑制","kind":"part"},{"id":"section-source-92-8","pageId":"source-92","title":"Part 4—Lysozyme Spectra—2D NOESY with WATERGATE Water","titleZh":"第 4 部分——溶菌酶谱：用 WATERGATE 抑水的二维 NOESY","kind":"part"},{"id":"section-source-94-9","pageId":"source-94","title":"Part 5—Ubiquitin Spectra—Shimming, Pulse Calibration and","titleZh":"第 5 部分——泛素谱：匀场、脉冲校准与","kind":"part"},{"id":"section-source-94-10","pageId":"source-94","title":"Part 6—Ubiquitin 2D 13C HSQC (Heteronuclear Single-","titleZh":"第 6 部分——泛素二维 13C HSQC（异核单量子）","kind":"part"},{"id":"section-source-96-11","pageId":"source-96","title":"Part 7—Ubiquitin 2D 15N HSQC Experiment Setup and","titleZh":"第 7 部分——泛素二维 15N HSQC 实验设置与","kind":"part"},{"id":"section-source-97-12","pageId":"source-97","title":"Part 8—Ubiquitin 2D HSQC Experiments Data Processing","titleZh":"第 8 部分——Ubiquitin 2D HSQC 实验的数据处理","kind":"part"},{"id":"section-source-98-13","pageId":"source-98","title":"SUMMARY","titleZh":"总结","kind":"section"},{"id":"section-source-98-14","pageId":"source-98","title":"APPENDIX 6.1 MAPPING SHIM PROFILES IN GRADSHIM","titleZh":"附录 6.1 在 gradshim 中绘制匀场剖面","kind":"section"},{"id":"section-source-101-15","pageId":"source-101","title":"APPENDIX 6.2 PRESAT180 PULSE SEQUENCE","titleZh":"附录 6.2 PRESAT180 脉冲序列","kind":"section"},{"id":"section-source-102-16","pageId":"source-102","title":"APPENDIX 6.3 X-NUCLEUS PULSE CALIBRATION","titleZh":"附录 6.3 X 核脉冲校准","kind":"section"},{"id":"section-source-103-17","pageId":"source-103","title":"APPENDIX 6.4 ROUTING FOR THE 15N RF CHANNEL IN THE","titleZh":"附录 6.4 15 N 射频通道的路由","kind":"section"}]});
